import { writeFileSync } from 'node:fs';

function evalExpr(cdp, expr) {
  return cdp
    .send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true })
    .then((r) => {
      if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails));
      return r.result.value;
    });
}
async function screenshot(cdp, path) {
  const res = await cdp.send('Page.captureScreenshot', { format: 'png' });
  writeFileSync(path, Buffer.from(res.data, 'base64'));
}
function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

async function run() {
  const { cdp, url } = await main();
  await cdp.send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
  await cdp.send('Page.navigate', { url });
  await sleep(1200);
  await evalExpr(cdp, "document.querySelector('#btn-start').click()");

  for (let i = 0; i < 20; i++) {
    await sleep(2500);
    const state = await evalExpr(cdp, 'JSON.stringify(window.__AETHERPLAY__)');
    console.log(`t+${(i + 1) * 2.5}s`, state);
    const parsed = JSON.parse(state);
    if (parsed.phase === 'won' || parsed.phase === 'lost') {
      await screenshot(cdp, `/tmp/shot-desktop-${parsed.phase}.png`);
      console.log('REACHED TERMINAL STATE:', parsed.phase);
      break;
    }
  }
  cdp.close();
  process.exit(0);
}

run().catch((err) => {
  console.error('FAILED', err);
  process.exit(1);
});
